// Fitness function F12 — Documentation agrees with results/ — why it matters
// architecturally: every headline number in the README and the docs is typed by
// hand, and everything in results/ is regenerated by a script. Those two drift
// apart silently, and that is how a paper ends up citing a figure nothing produces
// any more. Like F7 this is a static check of the repository as it stands: each
// registered claim is re-read from its document and compared with the value in
// results/*.json it is drawn from. The registry lives in tools/check-numbers.js.
import test from "node:test";
import assert from "node:assert/strict";
import { f12DocsAgreeWithResults } from "./props.js";

test("F12 — documentation agrees with results/", () => {
  const r = f12DocsAgreeWithResults();
  console.log(`FITNESS ${r.id} cases=${r.cases} passed=${r.passed} :: ${r.notes}`);
  assert.strictEqual(r.passed, true, r.notes);
});
